end_price = df['Close'].iloc[-1]
cumulative_return = (end_price / start_price - 1) * 100
days = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days
years = days / 365.25
cagr = (end_price / start_price) ** (1 / years) - 1
annualized_volatility = df['Daily_Return'].std() * np.sqrt(252)
df['RollingMax'] = df['Close'].cummax()
df['Drawdown'] = (df['Close'] - df['RollingMax']) / df['RollingMax']
max_drawdown = df['Drawdown'].min()
max_drawdown_date = df.loc[df['Drawdown'].idxmin(), 'Date']
peak_idx = df['Close'].iloc[:df['Drawdown'].idxmin()+1].idxmax()
peak_date = df.loc[peak_idx, 'Date']
peak_price = df.loc[peak_idx, 'Close']
total_dividends = df['Dividends'].sum()

# All-time high/low
ath_price = df['Close'].max()
ath_date = df.loc[df['Close'].idxmax(), 'Date']
atl_price = df['Close'].min()
atl_date = df.loc[df['Close'].idxmin(), 'Date']

# Decade stats
def decade_stats(decade_df):
    if len(decade_df) == 0:
        return {}
    start = decade_df['Close'].iloc[0]
    end = decade_df['Close'].iloc[-1]
    ret = (end / start - 1) * 100
    dr = decade_df['Daily_Return'].dropna()
    vol = dr.std() * np.sqrt(252) * 100 if len(dr) > 1 else 0
    divs = decade_df['Dividends'].sum()
    max_dd = ((decade_df['Close'] - decade_df['Close'].cummax()) / decade_df['Close'].cummax()).min() * 100
    years_dec = (decade_df['Date'].iloc[-1] - decade_df['Date'].iloc[0]).days / 365.25
    cagr_dec = (end / start) ** (1 / years_dec) - 1 if years_dec > 0 else 0
    return {
        'start_price': start,
        'end_price': end,
        'total_return_pct': ret,
        'cagr_pct': cagr_dec * 100,
        'volatility_pct': vol,
        'max_drawdown_pct': max_dd,
        'total_dividends': divs,
        'trading_days': len(decade_df)
    }

decades = [1970, 1980, 1990, 2000, 2010, 2020]
decade_data = {d: decade_stats(df[df['Decade'] == d]) for d in decades}

# Major drawdowns (>30%)
def find_major_drawdowns(df, min_depth=0.30):
    episodes = []
    in_dd = False
    start_idx = None
    peak_idx = None
    trough_idx = None
    trough_val = float('inf')
    peak_val = 0

    for i in range(len(df)):
        dd = df.loc[i, 'Drawdown']
        if not in_dd and dd <= -0.20:
            in_dd = True
            start_idx = i
            peak_idx = df.loc[:i, 'Close'].idxmax()
            peak_val = df.loc[peak_idx, 'Close']
            trough_idx = i
            trough_val = df.loc[i, 'Close']
        elif in_dd:
            if df.loc[i, 'Close'] < trough_val:
                trough_val = df.loc[i, 'Close']
                trough_idx = i
            if dd > -0.20:
                depth = (trough_val / peak_val - 1)
                if depth <= -min_depth:
                    episodes.append({
                        'peak_date': df.loc[peak_idx, 'Date'],
                        'trough_date': df.loc[trough_idx, 'Date'],
                        'peak_price': peak_val,
                        'trough_price': trough_val,
                        'depth_pct': depth * 100,
                        'recovery_date': df.loc[i, 'Date'],
                        'days_to_trough': (df.loc[trough_idx, 'Date'] - df.loc[peak_idx, 'Date']).days,
                        'days_to_recover': (df.loc[i, 'Date'] - df.loc[trough_idx, 'Date']).days
                    })
                in_dd = False

    merged = []
    for ep in episodes:
        if merged and abs((ep['peak_date'] - merged[-1]['peak_date']).days) < 30:
            if ep['depth_pct'] < merged[-1]['depth_pct']:
                merged[-1] = ep
        else:
            merged.append(ep)
    return merged

